WITH filtered_stores AS (SELECT * FROM stores WHERE sqft <= 14993 AND store_name LIKE 'Si%'), agg AS (SELECT CASE WHEN sqft >= 12487 THEN 'high' WHEN sqft >= 7711 THEN 'mid' ELSE 'low' END AS sqft_bucket, SUM(sqft) AS total_sqft FROM filtered_stores GROUP BY CASE WHEN sqft >= 12487 THEN 'high' WHEN sqft >= 7711 THEN 'mid' ELSE 'low' END) SELECT * FROM agg WHERE total_sqft > 73000 ORDER BY sqft_bucket DESC, 2 DESC
